package dev.smpcristalix.pvpcombat.listener;import dev.smpcristalix.pvpcombat.PvPCombatPlugin;import org.bukkit.Material;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.entity.ProjectileLaunchEvent;import org.bukkit.persistence.PersistentDataType;/** Метит снаряд арбалета, чтобы при попадании отличать его от лука. */public final class CrossbowListener implements Listener{@EventHandler(ignoreCancelled=true)public void onLaunch(ProjectileLaunchEvent e){if(!(e.getEntity().getShooter() instanceof Player p))return;if(p.getInventory().getItemInMainHand().getType()==Material.CROSSBOW||p.getInventory().getItemInOffHand().getType()==Material.CROSSBOW)e.getEntity().getPersistentDataContainer().set(PvPCombatPlugin.CROSSBOW_KEY,PersistentDataType.BYTE,(byte)1);}}
